// Package web embeds the statically exported frontend assets (web/out,
// produced by `npm run build`) into the Go binary, so that the `web`
// sub-command can serve the web UI without an external static file
// server such as nginx or caddy.
package web

import (
	"embed"
	"fmt"
	"io/fs"
)

// out/ is generated by `npm run build` and intentionally git-ignored; only a
// placeholder .gitkeep is tracked so that the embed pattern below always has
// at least one matching file and fresh clones still compile.
//
//go:embed all:out
var distFS embed.FS

const distRoot = "out"

// DistFS returns the embedded frontend distribution tree rooted at out/.
func DistFS() (fs.FS, error) {
	sub, err := fs.Sub(distFS, distRoot)
	if err != nil {
		return nil, fmt.Errorf("failed to sub-root embedded web assets at %q: %w", distRoot, err)
	}
	return sub, nil
}

// HasDistAssets reports whether real frontend assets were embedded into the
// binary (i.e. web/out existed with content at build time), as opposed to
// just the placeholder .gitkeep.
func HasDistAssets() bool {
	_, err := fs.Stat(distFS, distRoot+"/index.html")
	return err == nil
}
